mapper.sql:
WHERE workspace_id = #{workspaceId}


    AND id IN #{id}

  AND 1 = 0

  AND (search_name IS NULL OR search_phone IS NULL)

ORDER BY id LIMIT 500

mapper.update:
UPDATE 
SET search_name = CONVERT(#{nameKey,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler} USING utf8mb4),
    search_phone = CONVERT(#{phoneKey,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler} USING utf8mb4),
    search_key_revision = search_key_revision + 1, updated_at = updated_at
WHERE workspace_id = #{workspaceId} AND id = #{row.id} AND workspace_id = #{row.workspaceId}
  AND BINARY name <=> #{row.name,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler}
  AND BINARY phone <=> #{row.phone,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler}
  AND (search_name IS NULL OR search_phone IS NULL)
